#!/usr/bin/env python3
"""Operation spec for the riscv64 RVV fixed-length surface.

This module is data: the vector type universe, the generic
builtin opcode tables (shared by the shipped header and the
riscv64 backend), and the intrinsic family patterns the
header is generated from.  tools/riscv_gen.py consumes it.
"""

# ----------------------------------------------------------------
# type universe
# ----------------------------------------------------------------
# (kind, element bits, lmul) with lmul as an exact fraction
# string: mf8, mf4, mf2, m1, m2, m4, m8.  A fractional LMUL
# exists only when LMUL * ELEN >= 8 (the def-file type lists).
def _lmuls(elem):
    all_l = ["mf8", "mf4", "mf2", "m1", "m2", "m4", "m8"]
    frac = {8: 0, 16: 1, 32: 2, 64: 3}
    return all_l[frac[elem]:]

TYPES = []
for _kind in ("i", "u"):
    for _e in (8, 16, 32, 64):
        for _l in _lmuls(_e):
            TYPES.append((_kind, _e, _l))
for _l in _lmuls(32):
    TYPES.append(("f", 32, _l))
for _l in _lmuls(64):
    TYPES.append(("f", 64, _l))
BOOL_TYPES = [1, 2, 4, 8, 16, 32, 64]

def type_suffix(t):
    kind, e, l = t
    return "%s%d%s" % (kind, e, l)

def c_type(t):
    kind, e, l = t
    base = {"i": "vint", "u": "vuint", "f": "vfloat"}[kind]
    return "%s%d%s_t" % (base, e, l)

def c_scalar(t):
    kind, e, l = t
    return {"i": {8: "signed char", 16: "short", 32: "int", 64: "long"},
            "u": {8: "unsigned char", 16: "unsigned short",
                  32: "unsigned int", 64: "unsigned long"},
            "f": {32: "float", 64: "double"}}[kind][e]

# LMUL as a fraction (numerator, denominator)
LMUL_FRAC = {"mf8": (1, 8), "mf4": (1, 4), "mf2": (1, 2),
             "m1": (1, 1), "m2": (2, 1), "m4": (4, 1), "m8": (8, 1)}

def widen(t):
    """the type with twice the element width and twice the
    LMUL (the widening partner), or None"""
    kind, e, l = t
    if e == 64:
        return None
    n, d = LMUL_FRAC[l]
    n *= 2
    for name, (nn, dd) in LMUL_FRAC.items():
        if (nn, dd) == (n, d) or (n * dd == nn * d and nn * d == n * dd):
            pass
    inv = {v: k for k, v in LMUL_FRAC.items()}
    g = __import__("math").gcd(n, d)
    key = (n // g, d // g)
    if key not in inv:
        return None
    w = (kind, e * 2, inv[key])
    return w if w in TYPES else None

def lanes_at(t, vlen):
    kind, e, l = t
    n, d = LMUL_FRAC[l]
    return vlen * n // (d * e)

